section protocol-note-ladder
say "STEP name=note-ladder kind=note"
say "STEP-ABOUT F-AIR ladder for the merged provider module (opensource/docs/incoming/wifi-dp-air, hi5622_wifi.ko built by that lane's tools/build.sh; record size/sha256 from BUILD-NOTES.md and compare with sha256sum on the box - a mismatch is a STOP). Preconditions: attended session, recovery door READY, read-only UART capture, PD4 firmware + local Wi-Fi block staged, cfg80211.ko loaded first. One boot = one ide"
say "NOTE note-ladder: F-AIR ladder for the merged provider module (opensource/docs/incoming/wifi-dp-air, hi5622_wifi.ko built by that lane's tools/build.sh; record size/sha256 from BUILD-NOTES.md and compare with sha256sum on the box - a mismatch is a STOP). Preconditions: attended session, recovery door READY, read-only UART capture, PD4 firmware + local Wi-Fi block staged, cfg80211.ko loaded first. One boot = one ide"
say "GATE note-ladder.captured PASS"

section protocol-cfg-status
say "STEP name=cfg-status kind=attr_expect"
say "STEP-ABOUT wiphy registered after the ready handshake (cfg80211 preamble already waits for /sys/class/ieee80211; this is the sequence-local re-gate)"
r_attr_as seq-cfg-status cfg80211_status
  gate_attr 'cfg-status.p0' 'cfg80211_status' 'registered=1'

section protocol-pre-pack
say "STEP name=pre-pack kind=read_pack"
say "STEP-ABOUT pre-create state on this fresh boot: no context, exception mask 0, exception staging 0"
rd32 pre-pack.pre_ctx190 0x7D45E8
RD_pre_ctx190=$RDVAL
say "READ-OFF pre-pack.pre_ctx190 0x7D45E8"
  gate_num 'pre-pack.pre_ctx190' "$RD_pre_ctx190" zero 0xFFFFFFFF 0x00000000 0
rd32 pre-pack.pre_mask0 0x6F8008
RD_pre_mask0=$RDVAL
say "READ-OFF pre-pack.pre_mask0 0x6F8008"
  gate_num 'pre-pack.pre_mask0' "$RD_pre_mask0" zero 0xFFFFFFFF 0x00000000 0
rd32 pre-pack.pre_staging0 0x6F800C
RD_pre_staging0=$RDVAL
say "READ-OFF pre-pack.pre_staging0 0x6F800C"
  gate_num 'pre-pack.pre_staging0' "$RD_pre_staging0" zero 0xFFFFFFFF 0x00000000 0

section protocol-ctx-create-t1
say "STEP name=ctx-create-t1 kind=attr_write"
say "STEP-ABOUT H2D frame 1/3: ONE context-create (g0 id1 key 0x64, data[0]=type 1) - the ordered precondition of the TXQ sync, the provider VAP/scan frame family and the data-plane setup/hand-off"
w_attr h2d_ctx_create '1' 'ctx-create-t1'
say "GATE ctx-create-t1.write PASS"
r_attr_as seq-ctx-create-t1-h2d_status h2d_status
  gate_attr 'ctx-create-t1.p0' 'h2d_status' 'ctx_created=1'

section protocol-post-create
say "STEP name=post-create kind=read_pack"
say "STEP-ABOUT the create allocated the measured ctx4 body (same PACK as the hardware-validated C2/D2 rows: ctx4[0]=4, ctx4+0x10=0x00010001, ctx4+0x434=0x0100478C)"
rd32 post-create.post_ctx190 0x7D45E8
RD_post_ctx190=$RDVAL
say "READ-OFF post-create.post_ctx190 0x7D45E8"
  gate_num 'post-create.post_ctx190' "$RD_post_ctx190" nonzero 0xFFFFFFFF 0x00000000 0
rd32 post-create.post_ctx4 0x7D4458
RD_post_ctx4=$RDVAL
say "READ-OFF post-create.post_ctx4 0x7D4458"
  gate_num 'post-create.post_ctx4' "$RD_post_ctx4" eq 0xFFFFFFFF 0x00000004 0
rd32 post-create.post_ctx10 0x7D4468
RD_post_ctx10=$RDVAL
say "READ-OFF post-create.post_ctx10 0x7D4468"
  gate_num 'post-create.post_ctx10' "$RD_post_ctx10" eq 0xFFFFFFFF 0x00010001 0
rd32 post-create.post_ctx434 0x7D488C
RD_post_ctx434=$RDVAL
say "READ-OFF post-create.post_ctx434 0x7D488C"
  gate_num 'post-create.post_ctx434' "$RD_post_ctx434" eq 0xFFFFFFFF 0x0100478C 0

section protocol-txq-sync72
say "STEP name=txq-sync72 kind=attr_write"
say "STEP-ABOUT H2D frame 2/3: ONE TXQ config sync (g0 id1 cmd 0xd8, 72-byte node) -> core ACTIVE before the provider VAP/scan sequence (vap_start_first=1 needs the ACTIVE phase)"
w_attr h2d_txq_sync72 '1' 'txq-sync72'
say "GATE txq-sync72.write PASS"
r_attr_as seq-txq-sync72-h2d_status h2d_status
  gate_attr 'txq-sync72.p0' 'h2d_status' 'txq_sent=1'

section protocol-post-txq
say "STEP name=post-txq kind=read_pack"
say "STEP-ABOUT the TXQ handler ran clean: exception mask and staging word stay 0"
rd32 post-txq.txq_mask0 0x6F8008
RD_txq_mask0=$RDVAL
say "READ-OFF post-txq.txq_mask0 0x6F8008"
  gate_num 'post-txq.txq_mask0' "$RD_txq_mask0" zero 0xFFFFFFFF 0x00000000 0
rd32 post-txq.txq_staging0 0x6F800C
RD_txq_staging0=$RDVAL
say "READ-OFF post-txq.txq_staging0 0x6F800C"
  gate_num 'post-txq.txq_staging0' "$RD_txq_staging0" zero 0xFFFFFFFF 0x00000000 0

section protocol-vap-add
say "STEP name=vap-add kind=shell"
say "STEP-ABOUT iw phy phy0 interface add wlan0 type managed -> add_virtual_intf -> provider user_add g0 id7 180 B + user_add_notify g0 id8 180 B (hardware validated 2026-11-26)"
say "SHELL-CMD vap-add iw phy phy0 interface add wlan0 type managed"
section seq-vap-add
"$IW" 'phy' 'phy0' 'interface' 'add' 'wlan0' 'type' 'managed' > "$RDIR/seq-vap-add.out" 2>&1
SRC=$?
cat "$RDIR/seq-vap-add.out" >> "$R" 2>/dev/null || :
say "SHELL-RC vap-add rc=$SRC"
gate_rc 'vap-add.rc' "$SRC" 0

section protocol-link-up
say "STEP name=link-up kind=shell"
say "STEP-ABOUT bring the managed netdev up; nl80211 refuses the scan request on a down interface"
say "SHELL-CMD link-up ip link set wlan0 up"
section seq-link-up
'ip' 'link' 'set' 'wlan0' 'up' > "$RDIR/seq-link-up.out" 2>&1
SRC=$?
cat "$RDIR/seq-link-up.out" >> "$R" 2>/dev/null || :
say "SHELL-RC link-up rc=$SRC"
gate_rc 'link-up.rc' "$SRC" 0

section protocol-vap-added
say "STEP name=vap-added kind=attr_expect"
say "STEP-ABOUT the driver VAP model recorded the real wlan0 netdev"
r_attr_as seq-vap-added cfg80211_status
  gate_attr 'vap-added.p0' 'cfg80211_status' 'vap0: wlan0'

section protocol-catalog-baseline
say "STEP name=catalog-baseline kind=catalog_snapshot"
say "STEP-ABOUT D2H catalogue before the scan/data-plane ladder (evidence baseline)"
r_attr_as seq-catalog-baseline-rd_catalog rd_catalog
r_attr_as seq-catalog-baseline-rd_decode rd_decode
say "GATE catalog-baseline.captured PASS"

section protocol-scan
say "STEP name=scan kind=shell"
say "STEP-ABOUT ONE nl80211 scan: the provider posts vap_add g0 id1 48 B + vap_start g0 id1 40 B + scan_req g0 id0xC 520 B (hardware validated 2026-11-26; firmware pace ~3.5 s/channel so the auto window finishes with a channel-coverage or finish-abort result and results>0). This step is BOTH the mode-1 firmware VAP creation and the radio channel selection - the air-TX precondition. iw rc=0 also holds for an ABORT"
say "SHELL-CMD scan iw dev wlan0 scan"
section seq-scan
"$IW" 'dev' 'wlan0' 'scan' > "$RDIR/seq-scan.out" 2>&1
SRC=$?
cat "$RDIR/seq-scan.out" >> "$R" 2>/dev/null || :
say "SHELL-RC scan rc=$SRC"
if [ "$SRC" = "0" ]; then say "GATE scan PASS rc=$SRC"; else
  BLOCKED_HIT=0
  case "$SRC" in
    95|161) if grep -q 'Not supported' "$RDIR/seq-scan.out" 2>/dev/null || grep -q 'scan needs an H2D frame provider' "$RDIR/seq-scan.out" 2>/dev/null; then BLOCKED_HIT=1; fi;;
  esac
  if [ "$BLOCKED_HIT" = "1" ]; then say "BLOCKED scan rc=$SRC (documented pending feature)"; SEQ_BLOCKED=scan;
  else stop 'scan.rc' "exit code $SRC, expected 0"; fi
fi

section protocol-scan-settle
say "STEP name=scan-settle kind=sleep"
say "STEP-ABOUT bounded wait for the last firmware scan events to reach the direct reader and the driver's scan-done log"
sleep 1
say "GATE scan-settle.captured PASS"

section protocol-scan-results
say "STEP name=scan-results kind=attr_expect"
say "STEP-ABOUT PASS gate: the scan finished (ok or abort) and parsed at least one firmware result (g1 id15/17), so the firmware VAP object exists and the radio has a channel. BLOCKED-DRIVER: the scan was accepted but produced results=0 - the firmware produced nothing (the known VAP/scan-state wall), so the air-TX precondition is not met and the ladder must NOT claim a data-plane verdict"
r_attr_as seq-scan-results cfg80211_status
  ATTR_OK=1
  attr_has 'cfg80211_status' 'scan: phase=finished' || ATTR_OK=0
  attr_has 'cfg80211_status' 'results=' || ATTR_OK=0
  attr_has 'cfg80211_status' 'results=0' && ATTR_OK=0
  if [ "$ATTR_OK" = "1" ]; then
    say "GATE scan-results.p0 PASS (attr=cfg80211_status)"
    say "GATE scan-results.p1 PASS (attr=cfg80211_status)"
    say "GATE scan-results.a0 PASS (attr=cfg80211_status absent-pattern)"
  else
    BLOCKED_HIT=0
    attr_has 'cfg80211_status' 'results=0' && BLOCKED_HIT=1
    if [ "$BLOCKED_HIT" = "1" ]; then
      say "BLOCKED scan-results (documented pending outcome in attr cfg80211_status)"
      SEQ_BLOCKED=scan-results
    else
      stop 'scan-results' "attr cfg80211_status did not match the required gate"
    fi
  fi

section protocol-scan-dmesg
say "STEP name=scan-dmesg kind=shell"
say "STEP-ABOUT PASS gate: the cfg80211 scan event handler logged at least one 'scan channel result slot=.. ch=..' line (g1 id17 decode). BLOCKED-DRIVER: only the driver's own results=0 abort line is present"
say "SHELL-CMD scan-dmesg dmesg"
section seq-scan-dmesg
'dmesg' > "$RDIR/seq-scan-dmesg.out" 2>&1
SRC=$?
cat "$RDIR/seq-scan-dmesg.out" >> "$R" 2>/dev/null || :
say "SHELL-RC scan-dmesg rc=$SRC"
  OUT_OK=1
  [ "$SRC" = "0" ] || OUT_OK=0
  out_has "$RDIR/seq-scan-dmesg.out" 'scan channel result' || OUT_OK=0
  if [ "$OUT_OK" = "1" ]; then
    say "GATE 'scan-dmesg.rc' PASS rc=$SRC"
    say "GATE scan-dmesg.p0 PASS (shell)"
  else
    BLOCKED_HIT=0
    out_has "$RDIR/seq-scan-dmesg.out" 'scan DONE (finish-abort, results=0' && BLOCKED_HIT=1
    if [ "$BLOCKED_HIT" = "1" ]; then
      say "BLOCKED scan-dmesg rc=$SRC (documented pending feature)"
      SEQ_BLOCKED=scan-dmesg
    else
      stop 'scan-dmesg.rc' "exit code $SRC, expected 0"
    fi
  fi

section protocol-dp-probe
say "STEP name=dp-probe kind=attr_expect"
say "STEP-ABOUT read-only reachability word of MAC band 0 +0x00 (one read, no write); it must PASS before dp_setup is allowed in this load"
r_attr_as seq-dp-probe dp_probe
  gate_attr 'dp-probe.p0' 'dp_probe' 'dp_probe: MAC band0 CA 0x40040000'

section protocol-dp-setup
say "STEP name=dp-setup kind=attr_write"
say "STEP-ABOUT E1 (hardware-validated 2026-11-26): allocate the 0x2524 TXQ table, the 8x64x8 TX MSDU-info rings, tx_ba_info and the 256/512/4095 RX rings + 0x63c/0xb0 buffer pools; write the 8 device-RAM MSDU table entries {ring devVA,0,0}; program MAC band 0 with read-back. ONE action, no retry; a read-back mismatch closes the data-plane lane for this load."
w_attr dp_setup '1' 'dp-setup'
say "GATE dp-setup.write PASS"
r_attr_as seq-dp-setup-dp_status dp_status
  gate_attr 'dp-setup.p0' 'dp_status' 'setup_done=1'
  gate_attr 'dp-setup.p1' 'dp_status' 'failed=0'
  gate_attr 'dp-setup.p2' 'dp_status' 'mac_regs=14'
  gate_attr 'dp-setup.p3' 'dp_status' 'table_entries=8'

section protocol-dp-rings-check
say "STEP name=dp-rings-check kind=attr_expect"
say "STEP-ABOUT read-only MAC band 0 snapshot + device-RAM table read-out: the two free-ring write pointers published 0x8000 and the vendor interrupt mask 0xfffffcc1 are visible"
r_attr_as seq-dp-rings-check dp_rings
  gate_attr 'dp-rings-check.p0' 'dp_rings' '+0x38 = 0x00008000'
  gate_attr 'dp-rings-check.p1' 'dp_rings' '+0x3c = 0x00008000'
  gate_attr 'dp-rings-check.p2' 'dp_rings' '+0x48 = 0xfffffcc1'
  gate_attr 'dp-rings-check.p3' 'dp_rings' 'tid 7 entry'

section protocol-pre-tx-status
say "STEP name=pre-tx-status kind=attr_expect"
say "STEP-ABOUT the txrx layer bound to this load's E1 objects at the end of dp_setup; no frame posted yet"
r_attr_as seq-pre-tx-status dp_tx_status
  gate_attr 'pre-tx-status.p0' 'dp_tx_status' 'bound=1'
  gate_attr 'pre-tx-status.p1' 'dp_tx_status' 'failed=0'
  gate_attr 'pre-tx-status.p2' 'dp_tx_status' 'posted=0'

section protocol-dp-txq-sync
say "STEP name=dp-txq-sync kind=attr_write"
say "STEP-ABOUT H2D frame 3/3 and the data-plane hand-off: ONE g0 id1 key 0x0320 frame carrying the 4-byte device VA of the host-DRAM TXQ table (firmware worker CA 0x81445 stores it). The TX action gates on this commit; no retry."
w_attr h2d_txq_addr_sync '1' 'dp-txq-sync'
say "GATE dp-txq-sync.write PASS"
r_attr_as seq-dp-txq-sync-h2d_status h2d_status
  gate_attr 'dp-txq-sync.p0' 'h2d_status' 'txq_addr_sent=1'
  gate_attr 'dp-txq-sync.p1' 'h2d_status' 'ok=3'
  gate_attr 'dp-txq-sync.p2' 'h2d_status' 'timeout=0'
  gate_attr 'dp-txq-sync.p3' 'h2d_status' 'frames_sent=3'

section protocol-tx-frame-probe-req
say "STEP name=tx-frame-probe-req kind=attr_write"
say "STEP-ABOUT FIRST DATA-PLANE TX: 32-B broadcast probe request (802.11 mgmt, no FCS) into the coherent buffer [owner][16 B zero DMA header][MPDU]; 8-B MSDU entry for user 0/TID 0 slot 0 {buf devVA, ctl(len,tid0,vap1,hdr)}; dma_wmb; publish packed wptr 0->1 into the device-RAM 12-B table entry dword1 and read back all three dwords. One frame, no retry; broadcast has no ACK dependency."
w_attr dp_tx_frame '1' 'tx-frame-probe-req'
say "GATE tx-frame-probe-req.write PASS"
r_attr_as seq-tx-frame-probe-req-dp_tx_status dp_tx_status
  gate_attr 'tx-frame-probe-req.p0' 'dp_tx_status' 'posted=1'

section protocol-tx-status-1
say "STEP name=tx-status-1 kind=attr_expect"
say "STEP-ABOUT the post landed (entry + table wptr read back). completion_pending = distance(device rptr, published wptr): 0 = the MAC consumed the entry and wrote table dword2 (TX COMPLETED); 1 = POST-ONLY (host path proven, device did not consume). The completion read is NOT a gate: both are recorded outcomes"
r_attr_as seq-tx-status-1 dp_tx_status
  gate_attr 'tx-status-1.p0' 'dp_tx_status' 'posted=1'
  gate_attr 'tx-status-1.p1' 'dp_tx_status' 'vap_type=1'
  gate_attr 'tx-status-1.p2' 'dp_tx_status' 'completion_pending='
  gate_attr 'tx-status-1.p3' 'dp_tx_status' 'MSDU table entry'

section protocol-tx-frame-null
say "STEP name=tx-frame-null kind=attr_write"
say "STEP-ABOUT second frame (optional discrimination): 24-B broadcast null-data (data class, vap type 2) at ring slot 1 - settles the [I] ctl vap-type/header-flag mapping against the mgmt frame"
w_attr dp_tx_frame '2' 'tx-frame-null'
say "GATE tx-frame-null.write PASS"
r_attr_as seq-tx-frame-null-dp_tx_status dp_tx_status
  gate_attr 'tx-frame-null.p0' 'dp_tx_status' 'posted=2'

section protocol-tx-status-2
say "STEP name=tx-status-2 kind=attr_expect"
say "STEP-ABOUT both entries posted; completion_pending is captured as evidence for the COMPLETED vs POST-ONLY classification"
r_attr_as seq-tx-status-2 dp_tx_status
  gate_attr 'tx-status-2.p0' 'dp_tx_status' 'posted=2'
  gate_attr 'tx-status-2.p1' 'dp_tx_status' 'completion_pending='

section protocol-rx-poll
say "STEP name=rx-poll kind=attr_write"
say "STEP-ABOUT ONE read-only RX observation: bounded 2000 ms poll of MAC band 0 +0x4c (completion producer), then a scan of the host-DRAM 256 norm + 512 small RX buffers for the 0x28-B device descriptor. Moves NO ring pointer, reposts nothing; 0 completions is a recorded NO-RX outcome, never a gate"
w_attr dp_rx_poll '1' 'rx-poll'
say "GATE rx-poll.write PASS"
r_attr_as seq-rx-poll-dp_rx_capture dp_rx_capture
  gate_attr 'rx-poll.p0' 'dp_rx_capture' 'polled=1'

section protocol-rx-capture
say "STEP name=rx-capture kind=attr_expect"
say "STEP-ABOUT the captured evidence (MAC completion/norm/small counters, raw completion word, descriptor + up to 128 MPDU bytes) is read back; captures>0 with desc_ok=1 and a plausible 802.11 FC byte is the RX-descriptor evidence needed to decode the completion format in a later boot"
r_attr_as seq-rx-capture dp_rx_capture
  gate_attr 'rx-capture.p0' 'dp_rx_capture' 'polled=1'
  gate_attr 'rx-capture.p1' 'dp_rx_capture' 'captures='
  gate_attr 'rx-capture.p2' 'dp_rx_capture' 'note: descriptor field semantics'

section protocol-post-pack
say "STEP name=post-pack kind=read_pack"
say "STEP-ABOUT hard stop gate: no firmware exception and the golden handshake survived the provider ladder + MAC program + TX posts + RX capture"
rd32 post-pack.post_mask0 0x6F8008
RD_post_mask0=$RDVAL
say "READ-OFF post-pack.post_mask0 0x6F8008"
  gate_num 'post-pack.post_mask0' "$RD_post_mask0" zero 0xFFFFFFFF 0x00000000 0
rd32 post-pack.post_staging0 0x6F800C
RD_post_staging0=$RDVAL
say "READ-OFF post-pack.post_staging0 0x6F800C"
  gate_num 'post-pack.post_staging0' "$RD_post_staging0" zero 0xFFFFFFFF 0x00000000 0
rd32 post-pack.post_state0 0x7D0B60
RD_post_state0=$RDVAL
say "READ-OFF post-pack.post_state0 0x7D0B60"
  gate_num 'post-pack.post_state0' "$RD_post_state0" eq 0xFFFFFFFF 0x00000001 0
rd32 post-pack.post_page0 0x877000
RD_post_page0=$RDVAL
say "READ-OFF post-pack.post_page0 0x877000"
  gate_num 'post-pack.post_page0' "$RD_post_page0" eq 0xFFFFFFFF 0x86807FEF 0
rd32 post-pack.post_page4 0x877004
RD_post_page4=$RDVAL
say "READ-OFF post-pack.post_page4 0x877004"
  gate_num 'post-pack.post_page4' "$RD_post_page4" eq 0xFFFFFFFF 0x00000007 0
rd32 post-pack.post_page8 0x877008
RD_post_page8=$RDVAL
say "READ-OFF post-pack.post_page8 0x877008"
  gate_num 'post-pack.post_page8' "$RD_post_page8" eq 0xFFFFFFFF 0x00000002 0
rd32 post-pack.post_page_c 0x87700C
RD_post_page_c=$RDVAL
say "READ-OFF post-pack.post_page_c 0x87700C"
  gate_num 'post-pack.post_page_c' "$RD_post_page_c" eq 0xFFFFFFFF 0x0000ABCD 0
rd32 post-pack.post_out0 0x3F1010
RD_post_out0=$RDVAL
say "READ-OFF post-pack.post_out0 0x3F1010"
  gate_num 'post-pack.post_out0' "$RD_post_out0" zero 0xFFFFFFFF 0x00000000 0
rd32 post-pack.post_out2 0x3F12D4
RD_post_out2=$RDVAL
say "READ-OFF post-pack.post_out2 0x3F12D4"
  gate_num 'post-pack.post_out2' "$RD_post_out2" zero 0xFFFFFFFF 0x00000000 0

section protocol-h2d-summary
say "STEP name=h2d-summary kind=attr_expect"
say "STEP-ABOUT all three H2D frames (ctx-create, txq_sync72, key-0x0320 hand-off) were consumed; none was refused or timed out"
r_attr_as seq-h2d-summary h2d_status
  gate_attr 'h2d-summary.p0' 'h2d_status' 'timeout=0'
  gate_attr 'h2d-summary.p1' 'h2d_status' 'refused=0'
  gate_attr 'h2d-summary.p2' 'h2d_status' 'txq_addr_sent=1'

section protocol-catalog-after
say "STEP name=catalog-after kind=catalog_snapshot"
say "STEP-ABOUT post-run D2H catalogue delta (the TX entries have no known D2H answer; evidence only)"
r_attr_as seq-catalog-after-rd_catalog rd_catalog
r_attr_as seq-catalog-after-rd_decode rd_decode
say "GATE catalog-after.captured PASS"

section protocol-note-end
say "STEP name=note-end kind=note"
say "STEP-ABOUT F-AIR verdict: COMPLETED = posted frames landed AND completion_pending=0 (MAC consumed the MSDU entries); POST-ONLY = posted and completion_pending=1 for the whole read (host->ring->table path proven, MAC did not consume); NO-RX = RX capture polled with 0 completions (expected until the RX completion-word format is decoded); BLOCKED-DRIVER = the scan produced results=0 (no firmware VAP) so no air "
say "NOTE note-end: F-AIR verdict: COMPLETED = posted frames landed AND completion_pending=0 (MAC consumed the MSDU entries); POST-ONLY = posted and completion_pending=1 for the whole read (host->ring->table path proven, MAC did not consume); NO-RX = RX capture polled with 0 completions (expected until the RX completion-word format is decoded); BLOCKED-DRIVER = the scan produced results=0 (no firmware VAP) so no air "
say "GATE note-end.captured PASS"

say "SEQUENCE-END name=bringup-f-air-txrx"

section final
r_attr_as seq-final-h2d_status h2d_status
r_attr_as seq-final-h2d_plan h2d_plan
r_attr_as seq-final-hcc_events hcc_events
r_attr_as seq-final-hcc_ready hcc_ready
r_attr_as seq-final-hcc_status hcc_status
r_attr_as seq-final-boot boot
r_attr_as seq-final-rd_status rd_status
r_attr_as seq-final-rd_catalog rd_catalog
r_attr_as seq-final-rd_decode rd_decode
r_attr_as seq-final-cfg80211_status cfg80211_status
dmesg 2>/dev/null | tail -n 400 > "$RDIR/dmesg-final.txt" 2>/dev/null || :
section dmesg
cat "$RDIR/dmesg-final.txt" >> "$R" 2>/dev/null || :
section writes
say "WRITES-DEVICE total=$(wc -l < "$W")"
say "GATE no-cece-default PASS"
if [ -n "$SEQ_BLOCKED" ]; then
  say "SESSION_RESULT: BLOCKED:$SEQ_BLOCKED"
else
  say "SESSION_RESULT: PASS"
fi
section end
say "SESSION end=$(date +%s)"
